"""Read-only, bounded per-turn evidence for users; never model hidden reasoning."""from contextlib import contextmanagerfrom contextvars import ContextVarfrom datetime import datetime, timezonefrom html import escapefrom pathlib import Pathimport jsonimport reimport uuidfrom time import monotonicfrom functools import wraps_current = ContextVar("turn_process", default=None)def clean(value, depth=0):    if depth > 8:        return "…"    if isinstance(value, dict):        return {            str(k): clean(v, depth + 1)            for k, v in list(value.items())[:40]            if not any(                word in str(k).lower()                for word in ("key", "token", "password", "credential", "secret", "authorization")            )        }    if isinstance(value, (list, tuple)):        return [clean(v, depth + 1) for v in value[:30]]    if isinstance(value, str):        value = re.sub(r"(?i)\bBearer\s+\S+|\bsk-[A-Za-z0-9_-]+", "[已隐藏凭据]", value)        value = re.sub(            r"(?i)((?:api[_ -]?key|password|secret|token|密码)\s*[:=：]\s*)\S+",            r"\1[已隐藏凭据]",            value,        )        return value[:4000]    return value if value is None or isinstance(value, (bool, int, float)) else type(value).__name__def process_event(title, data):    record = _current.get()    if record is not None and len(record["events"]) < 30:        record["events"].append({"title": title, "data": clean(data)})def record_timing(name, seconds, *, category="node", status="completed", mode=None):    record = _current.get()    if record is not None and len(record.setdefault("timings", [])) < 80:        record["timings"].append(            {                "name": name,                "category": category,                "seconds": round(seconds, 3),                "status": status,                "mode": mode,            }        )def timed_call(name, callback, *args, category="node", mode=None, **kwargs):    started = monotonic()    status = "failed"    try:        result = callback(*args, **kwargs)        status = "completed"        return result    finally:        record_timing(name, monotonic() - started, category=category, status=status, mode=mode)def timed_node(name, node):    @wraps(node)    def measured(state, runtime):        return timed_call(name, node, state, runtime)    return measureddef proposal_summary(action):    if not isinstance(action, dict):        return {"result_type": type(action).__name__}    return {        k: action[k]        for k in (            "kind",            "answer",            "tool",            "target_ids",            "parameters",            "budget",            "reason",            "expected_purpose",            "evidence_refs",            "post_dft_review",            "round_budget_review",        )        if k in action    }@contextmanagerdef record_turn(runtime_config, message, thread_id):    config_path = Path(runtime_config)    root = config_path.resolve().parent    record = {        "id": uuid.uuid4().hex,        "time": datetime.now(timezone.utc).isoformat(),        "thread_id": thread_id,        "message": clean(message),        "events": [],        "timings": [],        "status": "进行中",    }    started = monotonic()    token = _current.set(record)    try:        try:            settings = json.loads(config_path.read_text(encoding="utf-8"))            state_path = root / settings.get("state_path", "workflow_state/state.json")            if state_path.is_file() and state_path.resolve().is_relative_to(root):                state = json.loads(state_path.read_text(encoding="utf-8"))                process_event(                    "读取的项目状态",                    {                        "配置版本": state.get("confirmed_config_version"),                        "任务数量": len(state.get("tasks") or []),                        "branch数量": len(state.get("branches") or []),                        "待审批方案数量": len(state.get("pending_execution_policies") or {}),                    },                )        except (OSError, ValueError, TypeError, AttributeError):            process_event("读取的项目状态", {"提示": "未能读取状态摘要，以业务检查结果为准"})        yield record        record["status"] = "已返回答复（执行结果以业务记录为准）"    except Exception as error:        process_event("本轮异常", {"type": type(error).__name__, "message": str(error)})        record["status"] = "异常结束"        raise    finally:        record["duration_seconds"] = round(monotonic() - started, 3)        _current.reset(token)        try:            directory = root / "workflow_state" / "dialogue_process"            directory.mkdir(parents=True, exist_ok=True)            target = directory / (record["id"] + ".json")            target.write_text(json.dumps(record, ensure_ascii=False, indent=2), encoding="utf-8")            # Keep a bounded local history, separate from scientific state.            for old in sorted(                directory.glob("*.json"), key=lambda p: p.stat().st_mtime, reverse=True            )[100:]:                old.unlink()        except OSError:            pass  # Diagnostics cannot turn a successful business action into a failure.def render_process_panel(runtime_config):    root = Path(runtime_config).resolve().parent    files = sorted(        (root / "workflow_state" / "dialogue_process").glob("*.json"),        key=lambda p: p.stat().st_mtime,        reverse=True,    )[:20]    cards = []    for path in files:        try:            record = json.loads(path.read_text(encoding="utf-8"))        except (OSError, ValueError):            continue        events = []        timings = record.get("timings") or []        if timings:            models = sum(row.get("category") == "model" for row in timings)            events.append(                "<p>本轮总耗时："                + escape(str(record.get("duration_seconds", "未知")))                + " 秒；模型调用："                + str(models)                + " 次。</p><details><summary>节点与模型耗时</summary><pre>"                + escape(                    json.dumps(                        sorted(timings, key=lambda row: row.get("seconds", 0), reverse=True),                        ensure_ascii=False,                        indent=2,                    )                )                + "</pre><p>父节点包含子步骤耗时，不能相加作为总耗时。</p></details>"            )        for event in record.get("events", []):            events.append(                "<details><summary>"                + escape(str(event["title"]))                + "</summary><pre>"                + escape(json.dumps(event["data"], ensure_ascii=False, indent=2))                + "</pre></details>"            )        cards.append(            "<section><h2>"            + escape(str(record.get("message", "")))            + "</h2><p>"            + escape(str(record.get("time", "")) + " · " + str(record.get("status", "")))            + "</p>"            + "".join(events)            + "</section>"        )    return (        """<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>本轮过程</title><style>body{font:16px/1.6 system-ui;background:#f4f6f8;color:#203040;max-width:1000px;margin:32px auto;padding:0 20px}section,details{background:white;padding:16px;border:1px solid #dce3ea;border-radius:10px;margin:12px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere}summary{cursor:pointer}h2{font-size:18px;overflow-wrap:anywhere}</style><h1>本轮过程</h1><p>查看实际读取的状态、模型提出的方案、校验错误及修正结果。这里只展示可核对的记录，不展示模型内部思维链。</p><p><a href="/phase/conversations">暂停／删除Studio对话</a> · <a href="/phase/process">刷新过程</a> · <a href="/phase/flow">科学流程与当前方案</a></p><p>依次展开：读取的项目状态 → 模型方案 → 方案校验 → 修正方案 → 本轮答复。出现校验错误表示该方案尚未通过；是否执行请核对最终答复和任务记录。本页不会重跑或批准任何操作。</p>"""        + (            "".join(cards)            or "<section>暂无过程记录。更新并启动服务后，在 Studio 发送一条新消息，再刷新本页。历史对话不会被补写成调试记录。</section>"        )        + "</html>"    )